  let i = 0;
  while (i < input.length) {
    const char = input[i];
    if (state === "normal") {
      if (char === " " || char === "\t") {
        if (current.length > 0 || hasQuotedContent) {
          args.push(current);
          current = "";
          hasQuotedContent = false;
        }
      } else if (char === '"') {
        state = "double";
        hasQuotedContent = true;
      } else if (char === "'") {
        state = "single";
        hasQuotedContent = true;
      } else {
        current += char;
      }
    } else if (state === "double") {
      if (char === "\\") {
        const next = input[i + 1];
        if (next === '"' || next === "\\") {
          current += next;
          i++;
        } else {
          current += char;
        }
      } else if (char === '"') {
        state = "normal";
      } else {
        current += char;
      }
    } else if (state === "single") {
      if (char === "\\") {
        const next = input[i + 1];
        if (next === "'" || next === "\\") {
          current += next;
          i++;
        } else {
          current += char;
        }
      } else if (char === "'") {
        state = "normal";
      } else {
        current += char;
      }
    }
    i++;
  }
  if (current.length > 0 || hasQuotedContent) {
